"""RelayVSR upscaling at the checkpoints' native x4 or x2: a keyframe every 15 frames generated by the keyframe model, each window of 16 frames
decoded from its two keyframes (the window's first frame, the previous window's last, decoded again for the video history and not emitted
twice). A call can hand its stream to the next one (Media Flow's chunks, each starting on the keyframe the previous one ended on): its
keyframe memory and last keyframe carry on, so that the chunks join as one long call would; a stream that starts after the first frame of
its source without one rebuilds its keyframe memory from the keyframes before it (a Media Flow job started or resumed there)."""
from __future__ import annotations

import gc
from dataclasses import dataclass

import torch
import torch.nn.functional as F
from accelerate import init_empty_weights
from mmgp import offload
from tqdm import tqdm

from postprocessing.memory import minimal_vram
from shared.utils import offload_registry
from shared.utils.media_control import controlled_model_loading, loading_callback
from .decoder import TOKEN_PIXELS, RelayVSRDecoder, Stream, previous_frame_rotation, rope_table
from .keyframes import LATENT_CHANNELS, SPATIAL_FACTOR, RelayVSRKeyframeModel

WINDOW_FRAMES = 16  # each window: a keyframe, 14 frames, the next keyframe
REPLAY_KEYFRAMES = 3  # keyframes before a stream's first frame that rebuild its keyframe memory (the memory holds the last 4 keyframes)
DTYPE = torch.bfloat16


@dataclass(frozen=True)
class RelayVSRPaths:
    keyframes: str
    decoder: str
    scale: int  # the checkpoints' native upscaling, 4 or 2


@dataclass(frozen=True)
class StreamReplay:
    """A stream starting at a frame of source that no carried stream continues: frames, the absolute indices of the keyframes before it
    (every WINDOW_FRAMES - 1 frames) that rebuild its keyframe memory."""
    source: str
    frames: tuple


class CarriedStream:
    """A stream the next call continues from its last keyframe: the keyframe memory, the decoder condition of that keyframe (in RAM between
    calls), the keyframe's absolute frame, its upscaled frame as this call decoded it (the next call emits it as its first frame, which it
    decodes again only for its history, as one long call would) and what the stream was made for (model, padded and output sizes, seed). A copy is the
    stream itself (the task settings that carry it are copied); the runtime releases it when a call does not continue it, when the models
    are released, or at the end of a Media Flow job."""

    def __init__(self, cache, condition, frame, last_frame, key):
        self.cache, self.condition, self.frame, self.last_frame, self.key = cache, condition, frame, last_frame, key

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

    def release(self):
        if self.cache is not None:
            self.cache.release()
        self.cache = self.condition = self.last_frame = None


def _move_condition(condition, device):
    """The decoder Condition's keys / values to device (blocking copies)."""
    condition.keys, condition.values = [tensor.to(device) for tensor in condition.keys], [tensor.to(device) for tensor in condition.values]
    return condition


def _replay_frames(replay: StreamReplay):
    """The source frames of a StreamReplay, uint8 (3, frames, height, width), decoded as WanGP decodes a postprocessing source."""
    from shared.utils.utils import get_resampled_video_transparent
    from shared.utils.virtual_media import build_virtual_media_path
    return torch.stack([get_resampled_video_transparent(build_virtual_media_path(replay.source, start_frame=frame, end_frame=frame), 0, 1, None)[0].permute(2, 0, 1) for frame in replay.frames], dim=1)


def kv_cache_bytes(height, width, padding):
    """The INT8 keyframe cache of a source of height x width pixels (padding: its pixels per keyframe token): 30 layers, 4 keyframes, keys
    and values of 3072 channels per token, with a FP16 scale per 32."""
    return -(-height // padding) * -(-width // padding) * 30 * 4 * 2 * 3072 * (1 + 1 / 16)


def _report(progress_callback, phase, current=None, total=None, unit=None):
    if callable(progress_callback):
        progress_callback(phase, current, total, unit)


class RelayVSRRuntime:
    def __init__(self):
        self.keyframes = self.decoder = self.offloadobj = self.loaded = self.stream = None

    @controlled_model_loading
    def load(self, paths: RelayVSRPaths, *, init_pipe, profile) -> None:
        if self.keyframes is not None and self.loaded == (paths, profile):
            return
        self.release()
        if not torch.cuda.is_available():
            raise RuntimeError("RelayVSR requires CUDA.")
        with init_empty_weights(include_buffers=True):
            keyframes, decoder = RelayVSRKeyframeModel(paths.scale), RelayVSRDecoder(paths.scale)
        offload.load_model_data(keyframes, paths.keyframes, writable_tensors=False, default_dtype=DTYPE, pre_load_callback=lambda model: model.lock_layers_dtypes(DTYPE), verboseLevel=-1)
        keyframes.apply_post_init_changes()
        offload.load_model_data(decoder, paths.decoder, writable_tensors=False, default_dtype=DTYPE, verboseLevel=-1)
        for model in (keyframes, decoder):
            model.eval().requires_grad_(False)
        pipe = {"transformer": keyframes, "decoder": decoder}
        kwargs = {"coTenantsMap": {"transformer": ["decoder"], "decoder": ["transformer"]}}
        profile_no = init_pipe(pipe, kwargs, profile)
        self.cache_in_ram = minimal_vram(kwargs)  # Postprocessor VRAM Usage: Minimum keeps the keyframe memory in RAM
        self.offloadobj = offload.profile(pipe, loading_callback=loading_callback(), profile_no=profile_no, quantizeTransformer=False, convertWeightsFloatTo=DTYPE, verboseLevel=-1, **kwargs)
        offload_registry.register_offloadobj("RelayVSR", self.offloadobj, self.release)
        self.keyframes, self.decoder, self.loaded = keyframes, decoder, (paths, profile)

    def release_stream(self) -> None:
        if self.stream is not None:
            self.stream.release()
            self.stream = None

    def release(self) -> None:
        self.release_stream()
        if self.offloadobj is not None:
            offload_registry.unregister_offloadobj("RelayVSR", self.offloadobj)
            self.offloadobj.release()
        self.keyframes = self.decoder = self.offloadobj = self.loaded = None
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    @torch.inference_mode()
    def upscale(self, sample: torch.Tensor, scale: float, *, seed: int = 0, frame_offset: int = 0, continue_cache=None, return_continue_cache: bool = False, abort_callback=None, progress_callback=None):
        """sample (3, frames, height, width), uint8 or float in [-1, 1], frame_offset: the absolute index of its first frame (the keyframes'
        noise follows it): (the upscaled frames, uint8 (3, frames, int(height * scale), int(width * scale)) in RAM, computed at the checkpoints'
        native scale and resized to the scale, and with return_continue_cache the CarriedStream the next call continues); (None, None) when
        aborted. continue_cache: the CarriedStream of the previous call, whose last keyframe is this sample's first frame, or a
        StreamReplay."""
        if self.keyframes is None:
            raise RuntimeError("RelayVSR models are not loaded.")
        from models.wan.modules.posemb_layers import set_use_fp32_rope_freqs
        set_use_fp32_rope_freqs(True)
        device = torch.device("cuda", torch.cuda.current_device())
        frame_count, (height, width) = sample.shape[1], sample.shape[-2:]
        native = self.keyframes.scale
        padding = SPATIAL_FACTOR // native  # low-resolution pixels per keyframe token
        padded_height, padded_width = height + (-height) % padding, width + (-width) % padding
        output_height, output_width = max(1, int(height * scale)), max(1, int(width * scale))
        rows, columns = padded_height * native // TOKEN_PIXELS, padded_width * native // TOKEN_PIXELS  # the latents' and decoder tokens' grid
        key = (id(self.keyframes), padded_height, padded_width, output_height, output_width, int(seed))
        carried = self.stream if continue_cache is not None and continue_cache is self.stream and self.stream.key == key and self.stream.frame == frame_offset else None
        if carried is None:
            self.release_stream()
        self.stream = None
        cache = carried.cache if carried is not None else self.keyframes.new_cache(padded_height * native, padded_width * native, device, in_ram=self.cache_in_ram)
        rope, rotation = rope_table(rows, columns, device), previous_frame_rotation(device)
        generator = torch.Generator(device=device)
        output = torch.empty((3, frame_count, output_height, output_width), dtype=torch.uint8, device="cpu")
        aborted = lambda: callable(abort_callback) and abort_callback()
        replay = continue_cache.frames if carried is None and isinstance(continue_cache, StreamReplay) else ()
        print(f"[RelayVSR] x{native} model, {width}x{height} -> {output_width}x{output_height}, {frame_count} frames, keyframe cache INT8 ({kv_cache_bytes(height, width, padding) / 2**30:.1f} GiB"
              + (", in RAM)" if self.cache_in_ram else ", in VRAM as far as it fits, the rest in RAM)" if cache.ring is not None else ", in VRAM)")
              + (", continuing the previous stream" if carried is not None else f", keyframe memory rebuilt from {len(replay)} keyframes" if replay else ""))

        def low_resolution(frame):
            """A frame (3, height, width), uint8 or float in [-1, 1], padded on the GPU."""
            uint8 = frame.dtype == torch.uint8
            frame = frame.to(device=device, dtype=torch.float32).unsqueeze(0)
            frame = frame.div_(127.5).sub_(1.0) if uint8 else frame.clamp_(-1.0, 1.0)
            return F.pad(frame, (0, padded_width - width, 0, padded_height - height), mode="replicate").to(DTYPE)

        def keyframe_latent(frame, absolute):
            """The latent of the keyframe of a low-resolution frame, its noise drawn from seed + its absolute index; None when aborted."""
            noise = torch.randn((1, LATENT_CHANNELS, 1, rows, columns), generator=generator.manual_seed(int(seed) + absolute), device=device, dtype=torch.float32)
            return self.keyframes.keyframe(low_resolution(frame), noise, cache, aborted)

        def keyframe(index):
            latent = keyframe_latent(sample[:, index], frame_offset + index)
            return None if latent is None else self.decoder.prime(latent.to(DTYPE), rope, aborted)

        def store(index, pixels):
            pixels = pixels[..., :height * native, :width * native]
            if (output_height, output_width) != pixels.shape[-2:]:
                pixels = F.interpolate(pixels.float(), size=(output_height, output_width), mode="bicubic", antialias=True)
            output[:, index] = pixels[0].float().clamp_(-1.0, 1.0).add_(1.0).mul_(127.5).round_().to(torch.uint8).cpu()

        kept = False
        try:
            if replay:
                frames = _replay_frames(continue_cache)
                if frames.shape[-2:] != (height, width):
                    raise ValueError(f"RelayVSR replay frames are {frames.shape[-1]}x{frames.shape[-2]}, the sample {width}x{height}")
                for number, absolute in enumerate(replay):
                    if keyframe_latent(frames[:, number], absolute) is None:
                        return None, None
                frames = None
            start, start_condition, first = 0, _move_condition(carried.condition, device) if carried is not None else keyframe(0), True
            carried_frame, carried = None if carried is None else carried.last_frame, None
            if start_condition is None:
                return None, None
            with tqdm(total=frame_count, desc="RelayVSR", unit="frame") as progress:
                while True:
                    end = min(start + WINDOW_FRAMES - 1, frame_count - 1)
                    end_condition = start_condition if end == start else keyframe(end)
                    if end_condition is None:
                        return None, None
                    stream = Stream(start_condition, end_condition, rows * columns, rows, columns, DTYPE, device)
                    for offset, index in enumerate(range(start, end + 1)):
                        pixels = self.decoder.decode(low_resolution(sample[:, index]), stream, rope, rotation, aborted)
                        if pixels is None:
                            return None, None
                        if first or offset:
                            if carried_frame is not None and index == 0:
                                output[:, 0], carried_frame = carried_frame, None
                            else:
                                store(index, pixels)
                            progress.update()
                            _report(progress_callback, "RelayVSR - Upscaling Frames", progress.n, frame_count, "frames")
                        pixels = None
                    stream.release()
                    first = False
                    if end == frame_count - 1:
                        if return_continue_cache:
                            self.stream, kept = CarriedStream(cache, _move_condition(end_condition, "cpu"), frame_offset + end, output[:, end].clone(), key), True
                        return output, self.stream
                    start, start_condition = end, end_condition
        finally:
            if not kept:
                cache.release()


_RUNTIME = RelayVSRRuntime()


def load_models(paths: RelayVSRPaths, *, init_pipe, profile):
    _RUNTIME.load(paths, init_pipe=init_pipe, profile=profile)


def upscale_video(sample, scale, **kwargs):
    return _RUNTIME.upscale(sample, scale, **kwargs)


def release_models():
    _RUNTIME.release()


def release_stream():
    """Releases the stream a call kept for the next one (the end of a Media Flow job)."""
    _RUNTIME.release_stream()


__all__ = ["CarriedStream", "RelayVSRPaths", "StreamReplay", "load_models", "release_models", "release_stream", "upscale_video"]
